  "difficulty": "Média",
  "statement": "Leia o poema “A última nau”, da obra Mensagem, de Fernando Pessoa, para responder às questões 09 e 10.\n\nLevando a bordo El-Rei D. Sebastião, E erguendo, como um nome, alto o pendão Do Império, Foi-se a última nau, ao sol aziago1\n\nErma2, e entre choros de ânsia e de pressago3\n\nMistério.\n\nNão voltou mais. A que ilha indescoberta Aportou? Voltará da sorte incerta Que teve? Deus guarda o corpo e a forma do futuro, Mas Sua luz projeta-o, sonho escuro E breve.\n\nAh, quanto mais ao povo a alma falta, Mais a minha alma atlântica se exalta E entorna, E em mim, num mar que não tem tempo ou spaço, Vejo entre a cerração teu vulto baço Que torna.\n\nNão sei a hora, mas sei que há a hora, Demore-a Deus, chame-lhe a alma embora Mistério. Surges ao sol em mim, e a névoa finda: A mesma, e trazes o pendão ainda Do Império.\n\n(Obra poética, 1987.)\n\n1 aziago: funesto.\n\n2 erma: solitária.\n\n3 pressago: presságio.\n\nEm relação ao poema “A última nau”, pode-se afirmar que:",
