  "statement": "Leia o texto para responder às questões 22 e 23.\n\nO Ocidente havia conhecido somente três modos de acesso ao poder: o nascimento, o mais importante, a riqueza, muito secundário até o século XIII salvo na Roma Antiga, o sorteio, de alcance limitado entre os cidadãos das cidades gregas da Antiguidade.\n\n(Jacques Le Goff. Os intelectuais na Idade Média, 1985. Adaptado.)\n\nO excerto sustenta que o acesso ao poder por meio da riqueza era secundário na Europa Ocidental até o século XIII, quando",
  "blockTypes": [
    "prose",
    "prose",
    "source",
    "command"
  ],
  "alternatives": [
    "as monarquias nacionais sobrepuseram-se aos direitos da nobreza senhorial sobre os seus feudos.",
    "os reis absolutistas constituíram seus exércitos com recursos de impostos arrecadados de banqueiros e comerciantes.",
    "a fragmentação econômica do continente europeu foi substituída por um só padrão monetário.",
    "o esfacelamento do poder imperial romano transferiu as funções de defesa militar para os burgueses das cidades.",
    "as atividades comerciais e artesanais produziram novos grupos sociais no interior das cidades medievais."
  ],
  "answer": "E",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "A questão se refere às transformações políticas produzidas na Europa Ocidental pelo Renascimento Comercial Urbano da Baixa Idade Média. Essa importante mudança socioeconômica apresentou, como um de seus resultados mais expressivos, o surgimento da burguesia – classe social emergente, enriquecida pelo comércio. A ação política dessa classe social manifestou-se na época de duas formas: apoiando a centralização monárquica contra a nobreza feudal ou criando sua própria autonomia, por meio do movimento comunal (emancipação das cidades). Outra classe surgida no período foi a dos artesãos, cuja atividade proporcionava à burguesia os produtos a serem comercializados."
  ],
  "resolutionMatched": true,
