  "subject": "Geografia",
  "content": "Urbanização e espaço urbano",
  "detail": "Urbanização e espaço urbano",
  "difficulty": "Média",
  "statement": "questão questão\n\nO Fórum Social Mundial (FSM) é um espaço internacional para reflexão e organização de todos os que estão construindo alternativas para favorecer o desenvolvimento humano e buscar a superação da dominação dos mercados. O FSM reuniu-se, pela primeira vez, na cidade de Porto Alegre em 2001, com o objetivo de se opor ao Fórum Econômico Mundial de Davos. O Fórum Econômico é financiado por mais de 1 000 empresas multinacionais e tem cumprido, desde 1971, papel estratégico na formulação de determinadas políticas em todo mundo.\n\n(www.forumsocialportoalegre.org.br. Adaptado.)\n\nO Fórum Social Mundial contrapõe-se às políticas",
  "blockTypes": [
    "prose",
    "prose",
    "source",
    "command"
  ],
  "alternatives": [
    "keynesianas, que promovem o controle do Estado sobre os setores relacionados à infraestrutura.",
    "de embargo econômico, que promovem a transferência de moedas para paraísos fiscais.",
    "neoliberais, que levam ao enfraquecimento dos mecanismos de controle estatal da economia.",
    "de planificação da economia, que levam à coexistência entre as propriedades estatais e as privadas.",
    "de reestruturação econômica, que promovem mudanças no âmbito da produção e da propriedade."
  ],
  "answer": "C",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "O advento da globalização pôs em evidência as ideias neoliberais, que pregam a saída do Estado da eco no - mia, deixando as atividades por conta da livre-ini cia - tiva. Essa postura já levou algumas economias à crise, como em 2008, e resultou numa reação dos grupos de esquerda que, ao contrário, pregam a presença mais atuante do Estado na economia."
  ],
  "resolutionMatched": true,
