  "difficulty": "Média",
  "statement": "A desertificação é um fenômeno que se desenvolve sobre ecossistemas fragilizados. Concebida como um fenômeno principalmente climático, a desertificação tem implicação sobretudo ecológica, daí falar-se em desertificação ecológica. Diferentemente da desertificação climática, a ecológica pode se desenvolver até mesmo em ambiente úmido, sendo que o elemento clima poderá não ter sofrido variação tão perceptível quanto aquela do manto vegetal e do solo promovidos pela ação humana.\n\n(Francisco Mendonça e Inês M. D. Oliveira. Climatologia, 2007. Adaptado.)\n\nConsiderando as informações apresentadas no excerto, constitui um indicador da desertificação ecológica a",
