  "detail": "Progressões e sequências",
  "difficulty": "Média",
  "statement": "As figuras indicam uma sequência de empilhamentos de cubos de 1 cm3. Da primeira pilha em diante, os volumes das pilhas, em cm3, são iguais a 1, 5, 14, 30, 55, e assim sucessivamente.",
