  "statementAfter": "Sabe-se que a soma 1 + 22 + 32 + 42 + 52 + ... + x2 é um polinômio do terceiro grau, dado por P(x) = mx3 + nx2 + px, com m, n e p racionais. Portanto, P(1) = 1, P(2) = 5, P(3) = 14, P(4) = 30 e assim por diante. Nas condições dadas, m é igual a"
