  "content": "Matemática integrada",
  "detail": "Matemática integrada",
  "difficulty": "Média",
  "statement": "Um granjeiro tem estoque de ração para alimentar 420 galinhas por 80 dias. Depois de x dias de uso desse estoque, o granjeiro vendeu 70 das 420 galinhas. Com a venda, o restante do estoque de ração durou 12 dias a mais do que esse restante de ração duraria se ele não tivesse vendido as galinhas. Supondo que o consumo diário de ração de cada galinha seja sempre o mesmo, x é igual a",
