    "Correta (B). Conforme a resolução: Sendo k a quantidade de ração que cada galinha consome por dia, as 420 galinhas consomem 420K por dia. Assim, a quantidade de ração que o granjeiro tinha no estoque é 420K . 80. Após x dias, a quantidade de galinhas será 420 – 70 = 350 e o estoque de ração 420K . 80 – 420K . x = 420K (80 – x) Logo, 420K . (80 – x) = 350K . (80 – x + 12) ⇒x = 20",
