  "statement": "As tomografias computadorizadas envolvem sobreposição de imagens e, em algumas situações, é necessário conhecer a área da região de intersecção das imagens sobrepostas. Na figura, um triângulo equilátero ABC se sobrepõe a um círculo de centro N e raio $NB = NC = NM$, com M e N sendo pontos médios, respectivamente, de $\\overline{AB}$ e $\\overline{BC}$.",
