  "difficulty": "Média",
  "statement": "A tabela indica a abundância aproximada de alguns dos gases presentes no ar atmosférico terrestre.\n\nGás % em volume\n\nOxigênio 21\n\nArgônio 0,94\n\nDióxido de carbono 0,035\n\nNeônio 0,0015",
  "blockTypes": [
    "prose",
    "prose",
    "prose",
    "prose",
    "prose",
    "prose"
  ],
  "parts": [
    {
      "id": "a",
      "prompt": "Quais desses gases são constituídos por átomos isolados?",
      "maxScore": 2,
      "expected": "Os gases são o argônio (1 ponto) e o neônio (1 ponto). Não foi aceita resposta com mais de dois gases.",
      "criteria": [
        {
          "points": 2,
          "text": "Atende integralmente às respostas esperadas e às condições de pontuação indicadas nos critérios oficiais."
        }
      ]
    },
    {
      "id": "b",
      "prompt": "Considere um local em que a pressão atmosférica seja 1 000 hPa. Calcule a pressão exercida por cada um desses quatro gases nesse local e a pressão total exercida pelos demais gases atmosféricos não incluídos na tabela.",
      "maxScore": 2,
      "expected": "A pressão parcial de cada gás em uma mistura gasosa é calculada pela lei das pressões parciais de Dalton: pressãogás = pressãototal × concentração Poxigênio = 1 000 hPa × 21/100 = 210 hPa Pargônio = 1 000 hPa × 0,94/100 = 9,4 hPa Pdióxido de carbono = 1 000 hPa × 0,035/100 = 0,35 hPa Pneônio = 1 000 hPa × 0,0015/100 = 0,015 hPa Pressão exercida pelos quatro gases = 210 + 9,4 + 0,35 + 0,015 = 219,765 hPa (1 ponto) Pela mesma lei, a pressão total de uma mistura gasosa corresponde à soma das pressões parciais dos gases constituintes. Assim, tem-se: Patmosférica = Pquatro gases + Pdemais gases 1 000 hPa = 219,765 hPa + Pdemais gases Pdemais gases = 1 000 hPa – 219,765 hPa = 780,235 hPa (1 ponto)",
      "criteria": [
        {
          "points": 2,
          "text": "Atende integralmente às respostas esperadas e às condições de pontuação indicadas nos critérios oficiais."
        }
      ]
    }
  ],
